BEGIN;
update public.vihem_system_settings set value=jsonb_set(value,'{enabled}','false') where key='push_notification_dispatch';
create function pg_temp.expect(label text,ok boolean) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.reject(label text,statement text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;if not failed then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create temp table f(o uuid,o2 uuid,a uuid,s uuid,client uuid,client2 uuid,route uuid,op uuid,second uuid,t timestamptz);
do $$declare o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();r uuid:=gen_random_uuid();begin
 insert into public.vihem_organisations(id,name,slug) values(o,'QA Snow','snow-'||o),(o2,'QA Other Snow','snow-'||o2);
 insert into auth.users(id,email) values(a,a||'@example.invalid'),(s,s||'@example.invalid');
 insert into public.vihem_profiles(id,organisation_id,name,email,role,active) values(a,o,'Snow Admin',a||'@example.invalid','admin',true),(s,o,'Snow Staff',s||'@example.invalid','snow',true) on conflict(id) do update set organisation_id=excluded.organisation_id,role=excluded.role,active=true;
 insert into public.vihem_organisation_modules(organisation_id,module_key,enabled) values(o,'snow',true),(o2,'snow',true) on conflict(organisation_id,module_key) do update set enabled=true;
 insert into public.vihem_permission_grants(organisation_id,user_id,permission_key) values(o,s,'module.snow');
 insert into public.vihem_time_categories(organisation_id,key,label,active) values(o,'snow_plowing','Snöröjning',true),(o,'snow_sanding','Sandning',true) on conflict do nothing;
 insert into public.vihem_snow_clients(id,organisation_id,name) values(c,o,'SVEVIA VIRSERUM'),(c2,o2,'Other org client');
 insert into public.vihem_snow_routes(id,organisation_id,client_id,name,method,geometry) values(r,o,c,'Prio route','machine','{"type":"LineString","coordinates":[[15.58,57.31],[15.59,57.32]]}');
 insert into public.vihem_jour_shifts(organisation_id,user_id,duty_type,starts_at,ends_at,source) values(o,s,'sno',now(),now()+interval '1 day','manual'),(o,a,'sno',now(),now()+interval '1 day','manual'),(o,a,'fastighet',now(),now()+interval '1 day','manual');
 insert into f values(o,o2,a,s,c,c2,r,gen_random_uuid(),gen_random_uuid(),now()-interval '20 minutes');
 perform set_config('request.jwt.claim.sub',s::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
end$$;
grant select on f to authenticated;
set local role authenticated;
select pg_temp.reject('jour-only external cannot start clock',format('select public.vihem_clock_transition(%L,%L,null,now(),%L::jsonb)',gen_random_uuid(),'clockin',jsonb_build_object('category','snow_plowing','snow_client_id',client,'snow_method','machine'))) from f;
select set_config('request.path','/rpc/create_notification',true),set_config('request.method','POST',true);
select pg_temp.reject('external cannot invoke unrelated security definer RPC','select public.vihem_snow_api_guard()');
select set_config('request.path','/vihem_jour_shifts',true),set_config('request.method','GET',true);
select public.vihem_snow_api_guard();
select pg_temp.expect('external sees own snow duty only',(select count(*)=1 from public.vihem_jour_shifts));
select pg_temp.expect('jour-only external cannot read customers',(select count(*)=0 from public.vihem_snow_clients));
reset role;
update public.vihem_profiles set snow_time_access=true where id=(select s from f);
set local role authenticated;
select pg_temp.expect('external can read only own profile',(select count(*)=1 from public.vihem_profiles));
select pg_temp.expect('external cannot read personnel time',(select count(*)=0 from public.vihem_time_entries));
select pg_temp.expect('external cannot read rental customers',(select count(*)=0 from public.vihem_rental_customers));
select pg_temp.expect('external cannot read work orders',(select count(*)=0 from public.vihem_work_orders));
select pg_temp.reject('external self promotion rejected',format('update public.vihem_profiles set role=%L where id=%L','admin',(select s from f)));
select pg_temp.expect('external cannot promote self',public.vihem_get_my_role()='snow');
select pg_temp.expect('snow staff sees only own organisation',(select count(*)=1 from public.vihem_snow_clients));
select pg_temp.reject('staff cannot edit route',format('select public.vihem_snow_save(%L,%L,1,%L::jsonb)','route',(select route from f),'{}'));
select public.vihem_clock_transition(op,'clockin',null,t,jsonb_build_object('category','snow_plowing','snow_client_id',client,'snow_route_id',route,'snow_method','machine'),'','Europe/Stockholm') from f;
select pg_temp.expect('snow pass in ordinary clock',(select count(*)=1 from public.vihem_time_entries where user_id=(select s from f) and category='snow_plowing' and snow_route_id=(select route from f) and customer_name='SVEVIA VIRSERUM'));
select public.vihem_clock_transition(op,'clockin',null,t,jsonb_build_object('category','snow_plowing','snow_client_id',client,'snow_route_id',route,'snow_method','machine'),'','Europe/Stockholm') from f;
select pg_temp.expect('duplicate tap remains one entry',(select count(*)=1 from public.vihem_time_entries where user_id=(select s from f)));
select pg_temp.reject('cross organisation customer rejected',format('select public.vihem_clock_transition(%L,%L,%L,%L,%L::jsonb)',gen_random_uuid(),'switch',op,t+interval '5 minutes',jsonb_build_object('category','snow_sanding','snow_client_id',client2,'snow_method','machine'))) from f;
select pg_temp.reject('wrong method and route rejected',format('select public.vihem_clock_transition(%L,%L,%L,%L,%L::jsonb)',gen_random_uuid(),'switch',op,t+interval '5 minutes',jsonb_build_object('category','snow_sanding','snow_client_id',client,'snow_route_id',route,'snow_method','hand'))) from f;
select pg_temp.expect('failed switch preserved open entry',(select end_time is null from public.vihem_time_entries where id=(select op from f)));
select public.vihem_snow_complete(op) from f;
select public.vihem_snow_complete(op) from f;
select pg_temp.expect('completion idempotent',(select count(*)=1 from public.vihem_snow_completions));
select public.vihem_clock_transition(second,'switch',op,t+interval '10 minutes',jsonb_build_object('category','snow_sanding','snow_client_id',client,'snow_method','hand'),'','Europe/Stockholm') from f;
select pg_temp.expect('switch has no comment requirement and correct minutes',(select total_minutes=10 and comment='' from public.vihem_time_entries where id=(select op from f)));
select pg_temp.reject('stale concurrent switch rejected',format('select public.vihem_clock_transition(%L,%L,%L,%L,%L::jsonb)',gen_random_uuid(),'switch',op,t+interval '11 minutes',jsonb_build_object('category','snow_sanding','snow_client_id',client,'snow_method','machine'))) from f;
select public.vihem_clock_transition(gen_random_uuid(),'lunch',second,t+interval '12 minutes','{}','','Europe/Stockholm') from f;
select pg_temp.expect('pause remains visible in own snow clock',(select count(*)=1 from public.vihem_time_entries where user_id=(select s from f) and end_time is null and snow_client_id is not null and entry_type='lunch'));
select public.vihem_clock_transition(gen_random_uuid(),'resume',(select id from public.vihem_time_entries where user_id=(select s from f) and end_time is null),t+interval '13 minutes','{}','','Europe/Stockholm') from f;
select pg_temp.expect('resume preserves customer activity and method',(select category='snow_sanding' and snow_method='hand' from public.vihem_time_entries where user_id=(select s from f) and end_time is null));
select public.vihem_clock_transition(gen_random_uuid(),'clockout',(select id from public.vihem_time_entries where user_id=(select s from f) and end_time is null),t+interval '15 minutes','{}','','Europe/Stockholm') from f;
select pg_temp.expect('clockout without comment closes same clock',(select count(*)=0 from public.vihem_time_entries where user_id=(select s from f) and end_time is null));
reset role;
select set_config('request.jwt.claim.sub',a::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from f;
set local role authenticated;
do $$declare x f%rowtype;schedule jsonb;begin select * into x from f;select jsonb_agg(jsonb_build_object('weekday',d,'active',false,'work_start','08:00','work_end','17:00','lunch_start',null,'lunch_minutes',0)) into schedule from generate_series(1,7) d;
 perform set_config('pgrst.db_pre_request','',true);
 perform pg_temp.reject('staff role save blocked before API guard activation',format('select public.vihem_save_staff_editor(%L,%L,%L::jsonb,%L::jsonb,ARRAY[]::text[],ARRAY[]::text[])',x.s,gen_random_uuid(),jsonb_build_object('name','QA Snow Staff','role','snow','active',true,'snow_time_access',true),schedule));
 perform set_config('pgrst.db_pre_request','public.vihem_snow_api_guard',true);
 perform public.vihem_save_staff_editor(x.s,gen_random_uuid(),jsonb_build_object('name','QA Snow Staff','phone','','role',(select role from public.vihem_profiles where id=x.s),'active',true,'bankid_personal_number','','is_system_admin',false,'snow_time_access',true),schedule,'{}','{}');
 perform pg_temp.expect('staff editor saves snow access atomically',(select snow_time_access from public.vihem_profiles where id=x.s));end$$;
select pg_temp.expect('missing geometry coordinates rejected',not public.vihem_snow_geometry_valid('{"type":"LineString"}'));
do $$declare id uuid:=gen_random_uuid();a jsonb;b jsonb;begin a:=public.vihem_snow_save('client',id,null,'{"name":"QA Retry Client"}');b:=public.vihem_snow_save('client',id,null,'{"name":"QA Retry Client"}');perform pg_temp.expect('save retry returns same client without duplicates',a=b);end$$;
select pg_temp.reject('malformed map geometry rejected',format('select public.vihem_snow_save(%L,%L,null,%L::jsonb)','route',gen_random_uuid(),jsonb_build_object('name','Bad shape','client_id',client,'method','machine','priority',1,'geometry','{"type":"Polygon","coordinates":[[[999,999]]]} '::jsonb))) from f;
select public.vihem_snow_save('client',client,1,'{"name":"SVEVIA VIRSERUM","active":false}') from f;
select pg_temp.reject('revision prevents lost edits',format('select public.vihem_snow_save(%L,%L,1,%L::jsonb)','client',client,'{"name":"Stale overwrite","active":true}')) from f;
reset role;
select pg_temp.expect('history retained after archiving',(select count(*)=4 from public.vihem_time_entries where user_id=(select s from f)));
update public.vihem_profiles set active=false where id=(select s from f);
select set_config('request.jwt.claim.sub',s::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.expect('inactive snow user denied',(select count(*)=0 from public.vihem_snow_clients));
reset role;
select pg_temp.expect('all unrelated RLS tables have external gate',not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity and c.relname like 'vihem_%' and c.relname not like 'vihem_snow_%' and not exists(select 1 from pg_policies p where p.tablename=c.relname and p.policyname='snow_external_read_gate')));
-- A shared-backend identity without a VI-HEM profile must keep existing storage access.
create policy snow_qa_storage_probe on storage.objects for select to authenticated using(bucket_id='snow-qa-compatibility');
insert into storage.buckets(id,name) values('snow-qa-compatibility','snow-qa-compatibility');
insert into storage.objects(bucket_id,name) values('snow-qa-compatibility','synthetic-metadata-only.txt');
select set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('request.jwt.claim.sub'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.expect('other-app identity retains permitted storage access',(select count(*)=1 from storage.objects where bucket_id='snow-qa-compatibility'));
reset role;
select set_config('request.jwt.claim.sub',s::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.expect('snow identity cannot use legacy storage policy',(select count(*)=0 from storage.objects where bucket_id='snow-qa-compatibility'));
reset role;
ROLLBACK;
